#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Car Counter (Two Ultrasonic Sensors)
// Increments on entry-then-exit trigger order, decrements on exit-then-entry.

const int TRIG1 = 9,  ECHO1 = 10; // entry-side sensor
const int TRIG2 = 11, ECHO2 = 12; // exit-side sensor

const int TRIGGER_DISTANCE_CM = 20; // something closer than this counts as "present"
const unsigned long SEQUENCE_TIMEOUT_MS = 1500; // max gap between the two triggers

enum State { IDLE, WAITING_FOR_SENSOR2, WAITING_FOR_SENSOR1 };
State state = IDLE;
unsigned long stateStartedAt = 0;

int count = 0;

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  pinMode(TRIG1, OUTPUT); pinMode(ECHO1, INPUT);
  pinMode(TRIG2, OUTPUT); pinMode(ECHO2, INPUT);

  lcd.init();
  lcd.backlight();
  updateDisplay();
}

void loop() {
  bool sensor1Triggered = readDistanceCm(TRIG1, ECHO1) < TRIGGER_DISTANCE_CM;
  bool sensor2Triggered = readDistanceCm(TRIG2, ECHO2) < TRIGGER_DISTANCE_CM;
  unsigned long now = millis();

  // Time out a stalled sequence (e.g. someone lingered under one sensor).
  if (state != IDLE && now - stateStartedAt > SEQUENCE_TIMEOUT_MS) {
    state = IDLE;
  }

  switch (state) {
    case IDLE:
      if (sensor1Triggered) {
        state = WAITING_FOR_SENSOR2;
        stateStartedAt = now;
      } else if (sensor2Triggered) {
        state = WAITING_FOR_SENSOR1;
        stateStartedAt = now;
      }
      break;

    case WAITING_FOR_SENSOR2:
      if (sensor2Triggered) {
        count++;
        state = IDLE;
        updateDisplay();
      }
      break;

    case WAITING_FOR_SENSOR1:
      if (sensor1Triggered) {
        count--;
        state = IDLE;
        updateDisplay();
      }
      break;
  }

  delay(50); // sensors need a brief gap between readings to avoid cross-interference
}

long readDistanceCm(int trigPin, int echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH, 30000);
  if (duration == 0) return 999;
  return duration / 58;
}

void updateDisplay() {
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Cars inside:");
  lcd.setCursor(0, 1);
  lcd.print(count);
}
